class Solution {
public:
    vector<vector<int>> combine(int n, int k) {
        vector<vector<int>> res;
        vector<int> path;
        auto dfs = [&](auto& self, int start) -> void {
            if ((int)path.size() == k) {
                res.push_back(path);
                return;
            }
            int need = k - (int)path.size();
            for (int i = start; i <= n - need + 1; ++i) {
                path.push_back(i);
                self(self, i + 1);
                path.pop_back();
            }
        };
        dfs(dfs, 1);
        return res;
    }
};

class Solution {
    public List<List<Integer>> combine(int n, int k) {
        List<List<Integer>> res = new ArrayList<>();
        dfs(1, n, k, new ArrayList<>(), res);
        return res;
    }
    private void dfs(int start, int n, int k, List<Integer> path, List<List<Integer>> res) {
        if (path.size() == k) {
            res.add(new ArrayList<>(path));
            return;
        }
        int need = k - path.size();
        for (int i = start; i <= n - need + 1; i++) {
            path.add(i);
            dfs(i + 1, n, k, path, res);
            path.remove(path.size() - 1);
        }
    }
}

var combine = function(n, k) {
    const res = [];
    const path = [];
    function backtrack(start) {
        if (path.length === k) {
            res.push([...path]);
            return;
        }
        const need = k - path.length;
        for (let i = start; i <= n - need + 1; i++) {
            path.push(i);
            backtrack(i + 1);
            path.pop();
        }
    }
    backtrack(1);
    return res;
};
